import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';

interface ReactionBody {
  messageId: string;
  emoji: string;
}

// Toggle a reaction on a message
async function toggleReaction(messageId: string, emoji: string) {
  const message = await db.message.findUnique({ where: { id: messageId } });
  if (!message) {
    return null;
  }

  const currentUserId = 'test-user-1';
  let reactions: Record<string, string[]> = {};

  if (message.reactions) {
    try {
      reactions = JSON.parse(message.reactions);
    } catch {
      reactions = {};
    }
  }

  // Toggle: remove if already exists, add if not
  if (reactions[emoji] && reactions[emoji].includes(currentUserId)) {
    reactions[emoji] = reactions[emoji].filter((uid: string) => uid !== currentUserId);
    if (reactions[emoji].length === 0) {
      delete reactions[emoji];
    }
  } else {
    if (!reactions[emoji]) {
      reactions[emoji] = [];
    }
    reactions[emoji].push(currentUserId);
  }

  const reactionsStr = Object.keys(reactions).length > 0
    ? JSON.stringify(reactions)
    : null;

  await db.message.update({
    where: { id: messageId },
    data: { reactions: reactionsStr },
  });

  return reactionsStr;
}

// POST /api/chat/reaction - add/remove reaction
export async function POST(request: NextRequest) {
  try {
    const body: ReactionBody = await request.json();
    const { messageId, emoji } = body;

    if (!messageId || !emoji) {
      return NextResponse.json(
        { error: 'messageId and emoji are required' },
        { status: 400 }
      );
    }

    const result = await toggleReaction(messageId, emoji);
    if (result === null) {
      return NextResponse.json(
        { error: 'Message not found' },
        { status: 404 }
      );
    }

    return NextResponse.json({ reactions: result });
  } catch (error) {
    console.error('Reaction error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

// PUT /api/chat/reaction - add/remove reaction (same as POST)
export async function PUT(request: NextRequest) {
  return POST(request);
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';

const CURRENT_USER = 'test-user-1';

// POST /api/chat/archive - toggle archive for a conversation
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { otherUserId } = body;

    if (!otherUserId) {
      return NextResponse.json({ error: 'otherUserId is required' }, { status: 400 });
    }

    // Verify the other user exists
    const otherUser = await db.user.findUnique({
      where: { id: otherUserId },
    });

    if (!otherUser) {
      return NextResponse.json({ error: 'Target user not found' }, { status: 404 });
    }

    // Find existing participant to toggle
    const existing = await db.conversationParticipant.findUnique({
      where: {
        userId_otherUserId: {
          userId: CURRENT_USER,
          otherUserId,
        },
      },
    });

    const newArchived = existing ? !existing.isArchived : true;

    const participant = await db.conversationParticipant.upsert({
      where: {
        userId_otherUserId: {
          userId: CURRENT_USER,
          otherUserId,
        },
      },
      create: {
        userId: CURRENT_USER,
        otherUserId,
        isArchived: newArchived,
      },
      update: {
        isArchived: newArchived,
      },
    });

    return NextResponse.json({ data: participant });
  } catch (error) {
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';

const CURRENT_USER = 'test-user-1';

// GET /api/chat/export?otherUserId=xxx - export messages as text/plain
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const otherUserId = searchParams.get('otherUserId');

    if (!otherUserId) {
      return NextResponse.json({ error: 'otherUserId is required' }, { status: 400 });
    }

    // Fetch both users for the header
    const [me, other] = await Promise.all([
      db.user.findUnique({ where: { id: CURRENT_USER }, select: { displayName: true, username: true } }),
      db.user.findUnique({ where: { id: otherUserId }, select: { displayName: true, username: true } }),
    ]);

    if (!me || !other) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }

    // Fetch all messages between the two users
    const messages = await db.message.findMany({
      where: {
        OR: [
          { senderId: CURRENT_USER, receiverId: otherUserId },
          { senderId: otherUserId, receiverId: CURRENT_USER },
        ],
        isDeleted: false,
        chatType: 'direct',
      },
      orderBy: { createdAt: 'asc' },
      include: {
        sender: { select: { displayName: true, username: true } },
      },
    });

    // Build text export
    const lines: string[] = [];
    lines.push(`NEXUS Chat Export`);
    lines.push(`Conversation: ${me.displayName} (@${me.username}) ↔ ${other.displayName} (@${other.username})`);
    lines.push(`Exported: ${new Date().toISOString()}`);
    lines.push(`Total messages: ${messages.length}`);
    lines.push('='.repeat(60));
    lines.push('');

    for (const msg of messages) {
      const timestamp = new Date(msg.createdAt).toLocaleString();
      const senderName = msg.sender.displayName;
      let content = msg.content;

      // Handle special message types
      if (msg.type === 'image') {
        content = msg.mediaUrl ? `[Image: ${msg.mediaUrl}]` : '[Image]';
      } else if (msg.type === 'video') {
        content = msg.mediaUrl ? `[Video: ${msg.mediaUrl}]` : '[Video]';
      } else if (msg.type === 'audio') {
        content = msg.mediaUrl ? `[Voice message: ${msg.mediaUrl}]` : '[Voice message]';
      } else if (msg.type === 'gift') {
        content = '[Gift sent]';
      } else if (msg.type === 'system') {
        content = `[System: ${content}]`;
      } else if (msg.type === 'sticker') {
        content = msg.mediaUrl ? `[Sticker: ${msg.mediaUrl}]` : '[Sticker]';
      }

      lines.push(`[${timestamp}] ${senderName}: ${content}`);
    }

    lines.push('');
    lines.push('='.repeat(60));
    lines.push('End of export');

    const text = lines.join('\n');

    return new NextResponse(text, {
      headers: {
        'Content-Type': 'text/plain; charset=utf-8',
        'Content-Disposition': `attachment; filename="chat-${me.username}-${other.username}.txt"`,
      },
    });
  } catch (error) {
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import ZAI from 'z-ai-web-dev-sdk';
const zai = new ZAI();

interface TranslateBody {
  text: string;
  targetLang: string;
}

// POST /api/chat/translate - translate message content using LLM
export async function POST(request: NextRequest) {
  try {
    const body: TranslateBody = await request.json();
    const { text, targetLang } = body;

    if (!text || !targetLang) {
      return NextResponse.json(
        { error: 'text and targetLang are required' },
        { status: 400 }
      );
    }

    const result = await zai.createChatCompletion({
      model: 'deepseek-chat',
      messages: [
        {
          role: 'user',
          content: `Translate the following text to ${targetLang}. Return ONLY the translated text, nothing else:\n\n${text}`,
        },
      ],
    });

    const translatedText = result.choices[0].message.content.trim();

    return NextResponse.json({ translatedText, targetLang });
  } catch (error) {
    console.error('Translate error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

