}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';

// GET /api/messages/conversations - list all conversations with last message, unread count, other user info
export async function GET() {
  try {
    const me = (await db.user.findUnique({ where: { id: 'test-user-1' } }))!;

    // Get all messages involving "me" that are not deleted
    const messages = await db.message.findMany({
      where: {
        chatType: 'direct',
        groupId: null,
        isDeleted: false,
        OR: [
          { senderId: me.id },
          { receiverId: me.id },
        ],
      },
      orderBy: { createdAt: 'desc' },
      include: {
        sender: {
          select: { id: true, username: true, displayName: true, avatar: true, online: true, lastSeen: true },
        },
        receiver: {
          select: { id: true, username: true, displayName: true, avatar: true, online: true, lastSeen: true },
        },
      },
    });

    // Group by conversation partner and keep the last message
    const conversationsMap = new Map<string, {
      otherUser: typeof messages[0]['sender'];
      lastMessage: typeof messages[0];
      unreadCount: number;
    }>();

    for (const msg of messages) {
      const otherUser = msg.senderId === me.id ? msg.receiver : msg.sender;
      if (!otherUser) continue;

      const otherId = otherUser.id;

      if (!conversationsMap.has(otherId)) {
        conversationsMap.set(otherId, {
          otherUser,
          lastMessage: msg,
          unreadCount: msg.receiverId === me.id && !msg.isRead ? 1 : 0,
        });
      }
    }

    const conversations = Array.from(conversationsMap.values()).sort(
      (a, b) => new Date(b.lastMessage.createdAt).getTime() - new Date(a.lastMessage.createdAt).getTime()
    );

    return NextResponse.json({ data: conversations });
  } catch (error) {
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';

const CURRENT_USER = 'test-user-1';

// PUT /api/contact-folders/[id] - rename folder
export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    const body = await request.json();
    const { name } = body;

    if (!name?.trim()) {
      return NextResponse.json({ error: 'name is required' }, { status: 400 });
    }

    const existing = await db.contactFolder.findFirst({
      where: { id, userId: CURRENT_USER },
    });

    if (!existing) {
      return NextResponse.json({ error: 'Folder not found' }, { status: 404 });
    }

    const folder = await db.contactFolder.update({
      where: { id },
      data: { name: name.trim() },
      include: { _count: { select: { members: true } } },
    });

    return NextResponse.json({ data: folder });
  } catch (error) {
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

// DELETE /api/contact-folders/[id] - delete folder (or remove member)
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    const { searchParams } = new URL(request.url);
    const targetUserId = searchParams.get('targetUserId');

    // If targetUserId provided, remove member
    if (targetUserId) {
      const folder = await db.contactFolder.findFirst({
        where: { id, userId: CURRENT_USER },
      });

      if (!folder) {
        return NextResponse.json({ error: 'Folder not found' }, { status: 404 });
      }

      await db.contactFolderMember.deleteMany({
        where: { folderId: id, targetUserId },
      });

      return NextResponse.json({ data: { removed: true } });
    }

    // Otherwise delete the whole folder
    const existing = await db.contactFolder.findFirst({
      where: { id, userId: CURRENT_USER },
    });

    if (!existing) {
      return NextResponse.json({ error: 'Folder not found' }, { status: 404 });
    }

    await db.contactFolder.delete({ where: { id } });

    return NextResponse.json({ data: { deleted: true } });
  } catch (error) {
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

// POST /api/contact-folders/[id] - add member
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    const body = await request.json();
    const { targetUserId } = body;

    if (!targetUserId) {
      return NextResponse.json({ error: 'targetUserId is required' }, { status: 400 });
    }

    const folder = await db.contactFolder.findFirst({
      where: { id, userId: CURRENT_USER },
    });

    if (!folder) {
      return NextResponse.json({ error: 'Folder not found' }, { status: 404 });
    }

    // Verify target user exists
    const targetUser = await db.user.findUnique({
      where: { id: targetUserId },
    });

    if (!targetUser) {
      return NextResponse.json({ error: 'Target user not found' }, { status: 404 });
    }

    const member = await db.contactFolderMember.create({
      data: {
        folderId: id,
        targetUserId,
      },
    });

    return NextResponse.json({ data: member }, { status: 201 });
  } catch (error: unknown) {
    if (error && typeof error === 'object' && 'code' in error && (error as { code: string }).code === 'P2002') {
      return NextResponse.json({ error: 'User is already in this folder' }, { status: 409 });
    }
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';

const CURRENT_USER = 'test-user-1';

// GET /api/contact-folders - list folders with member count
export async function GET() {
  try {
    const folders = await db.contactFolder.findMany({
      where: { userId: CURRENT_USER },
      orderBy: { createdAt: 'desc' },
      include: {
        _count: { select: { members: true } },
        members: {
          include: {
            folder: { select: { id: true, name: true } },
          },
        },
      },
    });

    // Enrich members with user details
    const enrichedFolders = await Promise.all(
      folders.map(async (folder) => {
        const memberIds = folder.members.map((m) => m.targetUserId);
        const users = memberIds.length > 0
          ? await db.user.findMany({
              where: { id: { in: memberIds } },
              select: { id: true, username: true, displayName: true, avatar: true, online: true },
            })
          : [];

        return {
          ...folder,
          memberUsers: users,
        };
      })
    );

    return NextResponse.json({ data: enrichedFolders });
  } catch (error) {
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

