// Haversine distance formula (returns km)
function haversine(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * Math.PI / 180) *
      Math.cos(lat2 * Math.PI / 180) *
      Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// GET /api/users - list users with pagination, filters, and real haversine distances
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '20');
    const search = searchParams.get('search') || '';
    const lookingFor = searchParams.get('lookingFor') || '';
    const minAge = parseInt(searchParams.get('minAge') || '0');
    const maxAge = parseInt(searchParams.get('maxAge') || '150');
    const onlineStatus = searchParams.get('online') || '';
    const refLat = parseFloat(searchParams.get('lat') || '35.8969');
    const refLng = parseFloat(searchParams.get('lng') || '14.4425');
    const skip = (page - 1) * limit;

    const where: Record<string, unknown> = {};

    if (search) {
      where.OR = [
        { displayName: { contains: search } },
        { username: { contains: search } },
        { bio: { contains: search } },
      ];
    }

    if (lookingFor) {
      where.lookingFor = lookingFor;
    }

    if (minAge > 0 || maxAge < 150) {
      where.age = {};
      if (minAge > 0) (where.age as Record<string, number>).gte = minAge;
      if (maxAge < 150) (where.age as Record<string, number>).lte = maxAge;
    }

    if (onlineStatus === 'true') {
      where.online = true;
    } else if (onlineStatus === 'false') {
      where.online = false;
    }

    const [users, total] = await Promise.all([
      db.user.findMany({
        where,
        skip,
        take: limit,
        orderBy: { lastSeen: 'desc' },
        select: {
          id: true,
          username: true,
          displayName: true,
          avatar: true,
          bio: true,
          age: true,
          gender: true,
          location: true,
          lat: true,
          lng: true,
          online: true,
          lastSeen: true,
          isPremium: true,
          isVerified: true,
          lookingFor: true,
          pronouns: true,
          showOnline: true,
          showDistance: true,
          showAge: true,
          createdAt: true,
          _count: {
            select: { photos: true },
          },
        },
      }),
      db.user.count({ where }),
    ]);

    // Calculate real haversine distance
    const usersWithDistance = users.map((user) => {
      let distance: number | null = null;
      if (user.lat && user.lng) {
        distance = Math.round(haversine(refLat, refLng, user.lat, user.lng) * 10) / 10;
      }
      return {
        ...user,
        distance,
      };
    });

    return NextResponse.json({
      data: usersWithDistance,
      pagination: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit),
      },
    });
  } catch (error) {
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

