import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';

// GET /api/events/upcoming - return real events from DB sorted by startDate with optional type filter
// Query params: ?type=social|party|meetup|sports|cultural
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const typeFilter = searchParams.get('type');

    // Fetch real events from DB
    const whereClause: Record<string, unknown> = { isPublic: true };
    if (typeFilter) {
      whereClause.type = typeFilter;
    }

    const dbEvents = await db.event.findMany({
      where: whereClause,
      orderBy: { startDate: 'asc' },
    });

    // Map DB events to consistent format
    const formattedEvents = dbEvents.map((e) => ({
      id: e.id,
      title: e.title,
      description: e.description,
      location: e.location,
      lat: e.lat,
      lng: e.lng,
      startDate: e.startDate.toISOString(),
      endDate: e.endDate?.toISOString() || null,
      imageUrl: e.imageUrl,
      type: e.type,
      attendeeCount: e.attendeeCount,
      isPublic: e.isPublic,
    }));

    // Build type counts from DB events
    const typeCounts: Record<string, number> = {};
    for (const e of dbEvents) {
      if (e.type) {
        typeCounts[e.type] = (typeCounts[e.type] || 0) + 1;
      }
    }

    return NextResponse.json({
      data: formattedEvents,
      total: formattedEvents.length,
      typeCounts,
      filter: typeFilter || null,
    });
  } catch (error) {
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';

// GET /api/events - list events with optional RSVP filter
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const rsvpStatus = searchParams.get('rsvp') || '';
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '20');
    const skip = (page - 1) * limit;

    const events = await db.event.findMany({
      where: { isPublic: true },
      skip,
      take: limit,
      orderBy: { startDate: 'asc' },
      include: {
        owner: {
          select: { id: true, username: true, displayName: true, avatar: true, isVerified: true },
        },
        _count: {
          select: { rsvps: true },
        },
        rsvps: rsvpStatus
          ? {
              where: { status: rsvpStatus },
              select: {
                user: { select: { id: true, username: true, displayName: true, avatar: true } },
              },
            }
          : false,
      },
    });

    return NextResponse.json({
      data: events,
      pagination: { page, limit },
    });
  } catch (error) {
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

// POST /api/events - create event or RSVP
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { action } = body;

    if (action === 'rsvp') {
      // RSVP to an event
      const { eventId, status } = body;

      if (!eventId || !status) {
        return NextResponse.json({ error: 'eventId and status are required' }, { status: 400 });
      }

      const me = (await db.user.findUnique({ where: { id: 'test-user-1' } }))!;

      const rsvp = await db.eventRSVP.upsert({
        where: { userId_eventId: { userId: me.id, eventId } },
        create: { userId: me.id, eventId, status },
        update: { status },
        include: {
          user: { select: { id: true, username: true, displayName: true, avatar: true } },
          event: { select: { id: true, title: true } },
        },
      });

      return NextResponse.json({ data: rsvp });
    }

    // Create event
    const { title, description, location, lat, lng, startDate, endDate, imageUrl, isPublic } = body;

    if (!title || !startDate) {
      return NextResponse.json({ error: 'title and startDate are required' }, { status: 400 });
    }

    const me = (await db.user.findUnique({ where: { id: 'test-user-1' } }))!;

    const event = await db.event.create({
      data: {
        title,
        description: description || null,
        location: location || null,
        lat: lat || null,
        lng: lng || null,
        startDate: new Date(startDate),
        endDate: endDate ? new Date(endDate) : null,
        imageUrl: imageUrl || null,
        isPublic: isPublic ?? true,
        ownerId: me.id,
      },
      include: {
        owner: {
          select: { id: true, username: true, displayName: true, avatar: true },
        },
      },
    });

    return NextResponse.json({ data: event }, { status: 201 });
  } catch (error) {
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

