            <SectionHeader icon={Navigation} label="Location Mode" />
            {modes.map(mode => {
              const Icon = mode.icon;
              return (
                <button key={mode.value} onClick={() => { setGeoMode(mode.value); setPrefs(p => ({ ...p, geoMode: mode.value })); }}
