          </CardContent></Card>
          <Button variant="outline" className="w-full border-destructive/30 text-destructive hover:bg-destructive/10" onClick={() => { setCurrentUser(null); setAuthed(false); setShowSettings(false); }}><LogOut className="w-4 h-4 mr-2" /> Log Out</Button>
          <div className="h-4" />
        </div>
      </ScrollArea>
    );
  }
}

@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

:root {
  --radius: 0.625rem;
  --background: oklch(0.13 0.005 285);
  --foreground: oklch(0.95 0 0);
  --card: oklch(0.18 0.005 285);
  --card-foreground: oklch(0.95 0 0);
  --popover: oklch(0.18 0.005 285);
  --popover-foreground: oklch(0.95 0 0);
  --primary: oklch(0.75 0.15 320);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.22 0.005 285);
  --secondary-foreground: oklch(0.90 0 0);
  --muted: oklch(0.22 0.005 285);
  --muted-foreground: oklch(0.65 0 0);
  --accent: oklch(0.25 0.02 320);
  --accent-foreground: oklch(0.95 0 0);
  --destructive: oklch(0.65 0.22 25);
  --border: oklch(1 0 0 / 8%);
  --input: oklch(1 0 0 / 12%);
  --ring: oklch(0.75 0.15 320);
  --chart-1: oklch(0.75 0.15 320);
  --chart-2: oklch(0.7 0.15 180);
  --chart-3: oklch(0.75 0.12 60);
  --chart-4: oklch(0.65 0.2 280);
  --chart-5: oklch(0.7 0.18 150);
  --sidebar: oklch(0.15 0.005 285);
  --sidebar-foreground: oklch(0.95 0 0);
  --sidebar-primary: oklch(0.75 0.15 320);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.22 0.01 285);
  --sidebar-accent-foreground: oklch(0.95 0 0);
  --sidebar-border: oklch(1 0 0 / 8%);
  --sidebar-ring: oklch(0.75 0.15 320);
}

.dark {
  --background: oklch(0.13 0.005 285);
  --foreground: oklch(0.95 0 0);
  --card: oklch(0.18 0.005 285);
  --card-foreground: oklch(0.95 0 0);
  --popover: oklch(0.18 0.005 285);
  --popover-foreground: oklch(0.95 0 0);
  --primary: oklch(0.75 0.15 320);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.22 0.005 285);
  --secondary-foreground: oklch(0.90 0 0);
  --muted: oklch(0.22 0.005 285);
  --muted-foreground: oklch(0.65 0 0);
  --accent: oklch(0.25 0.02 320);
  --accent-foreground: oklch(0.95 0 0);
  --destructive: oklch(0.65 0.22 25);
  --border: oklch(1 0 0 / 8%);
  --input: oklch(1 0 0 / 12%);
  --ring: oklch(0.75 0.15 320);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

/* Custom scrollbar - FYK style */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: oklch(1 0 0 / 15%);
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: oklch(1 0 0 / 25%);
}

/* Profile card hover glow */
.profile-card {
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.profile-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 30px oklch(0 0 0 / 40%), 0 0 0 1px oklch(0.75 0.15 320 / 20%);
}

/* Online indicator pulse */
@keyframes pulse-online {
  0%, 100% { box-shadow: 0 0 0 0 oklch(0.7 0.2 145 / 40%); }
  50% { box-shadow: 0 0 0 6px oklch(0.7 0.2 145 / 0%); }
}
.online-pulse {
  animation: pulse-online 2s ease-in-out infinite;
}

/* Gradient text for premium */
.gradient-text {
  background: linear-gradient(135deg, oklch(0.8 0.18 320), oklch(0.75 0.15 280));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Bottom nav active indicator */
.nav-active {
  position: relative;
}
.nav-active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 50%;
  transform: translateX(-50%);
  width: 20px;
  height: 3px;
  background: oklch(0.75 0.15 320);
  border-radius: 2px;
}

/* Cascade card animation */
@keyframes cascade-in {
  from { opacity: 0; transform: scale(0.95) translateY(20px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}
.cascade-animate {
  animation: cascade-in 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Boost glow */
@keyframes boost-glow {
  0%, 100% { box-shadow: 0 0 10px oklch(0.75 0.15 320 / 30%); }
  50% { box-shadow: 0 0 25px oklch(0.75 0.15 320 / 60%); }
}
.boost-glow {
  animation: boost-glow 2s ease-in-out infinite;
}

/* Leaflet map dark theme overrides */
.leaflet-container {
  background: oklch(0.13 0.005 285) !important;
  font-family: inherit;
}
.leaflet-control-zoom a {
  background: oklch(0.18 0.005 285) !important;
  color: oklch(0.95 0 0) !important;
  border-color: oklch(1 0 0 / 8%) !important;
}
.leaflet-control-zoom a:hover {
  background: oklch(0.25 0.02 285) !important;
}
.leaflet-popup-content-wrapper {
  background: oklch(0.18 0.005 285);
  color: oklch(0.95 0 0);
  border-radius: 12px;
}
.leaflet-popup-tip {
  background: oklch(0.18 0.005 285);
}

