              key={t.id}
              onClick={() => { setChatTheme(t.id); setShowThemeModal(false); }}
              className={`p-3 rounded-xl border-2 transition-all ${chatTheme === t.id ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/30'}`}
